trigger OpportunityDiscountGuard on Opportunity (before insert, before update) {
    for (Opportunity opp : Trigger.new) {
        if (opp.Discount__c != null && opp.Discount__c > 0.5) {
            opp.addError('Discount exceeds hard policy limit of 50%.');
        }
        if (opp.Amount != null && opp.Amount < 0) {
            String msg = 'Amount must be positive: ' + opp.Amount;
            opp.addError(msg);
        }
    }
}
